import math

def psi(expected, actual, edges, eps=1e-4):
    def frac(data):
        counts = [0] * (len(edges) - 1)
        for x in data:
            for i in range(len(edges) - 1):
                if edges[i] <= x < edges[i + 1]:
                    counts[i] += 1
                    break
        n = len(data)
        return [max(c / n, eps) for c in counts]
    e, a = frac(expected), frac(actual)
    return sum((ai - ei) * math.log(ai / ei) for ei, ai in zip(e, a))

edges = [float("-inf"), 25, 50, 75, float("inf")]
ref = list(range(100))
print("identical:", round(psi(ref, ref, edges), 3))
print("shift +15:", round(psi(ref, [x + 15 for x in ref], edges), 3))
print("shift +40:", round(psi(ref, [x + 40 for x in ref], edges), 3))

import math

def train_features(raw):
    return {"age": raw["age"],
            "income_log": math.log1p(raw["income"]),
            "city_len": len(raw["city"].strip().lower())}

def serve_features(raw):            # buggy re-implementation
    return {"age": raw["age"],
            "income_log": raw["income"],
            "city_len": len(raw["city"])}

golden = [{"age": 30, "income": 50000, "city": " Paris"},
          {"age": 41, "income": 0, "city": "rome"}]

bad = set()
for raw in golden:
    t, s = train_features(raw), serve_features(raw)
    for k in t:
        if abs(t[k] - s[k]) > 1e-9:
            bad.add(k)
print("skewed features:", sorted(bad))
print("parity ok:", not bad)
